settings.cellContentFunction:
// value is epoch millis
if (!value) {
    return '';
}
var d = new Date(value);
if (isNaN(d.getTime())) {
    return '';
}

// dd-MM-yyyy HH:mm
function pad(n) { return n < 10 ? '0' + n : '' + n; }

var day    = pad(d.getDate());
var month  = pad(d.getMonth() + 1);
var year   = d.getFullYear();
var hours  = pad(d.getHours());
var mins   = pad(d.getMinutes());

return day + '/' + month + '/' + year + ' ' + hours + ':' + mins;

settings.cellStyleFunction:
var style = {
  display: 'inline-block',
  'min-width': '48px',
  padding: '2px 6px',
  'border-radius': '12px',
  color: '#ffffff',
  'font-weight': 600,
  'font-size': '10px',
  'text-transform': 'uppercase',
  'text-align': 'center'
};

switch (String(value).toUpperCase()) {
  case 'CRITICAL':
  case 'MAJOR':
  case 'HIGH':
    style['background-color'] = '#d32f2f';  // red
    break;
  case 'MINOR':
  case 'WARNING':
  case 'MEDIUM':
    style['background-color'] = '#fb8c00';  // orange
    break;
  case 'INDETERMINATE':
  default:
    style['background-color'] = '#43a047';  // green
    break;
}

return style;

