config.widgetCss:
/* Make the widget card fill the space and remove extra padding */
:host {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Remove inner mat-card padding ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ we are styling the whole card ourselves */
.mat-card {
  height: 100%;
  padding: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

/* OPTIONAL: hide the time window / toolbar row if you want it very clean */
/* Comment this block out if you want to keep "Realtime ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ last day" */
.mat-card .mat-toolbar,
.mat-card .tb-alarms-header {
  display: none !important;
}

/* Table container */
.mat-table {
  width: 100%;
  border-collapse: collapse;
  background: #ffffff;
}

/* Header row */
.mat-header-row {
  background: #f6f7f9;
}

.mat-header-cell {
  padding: 6px 8px;
  font-size: 10px;
  font-weight: 600;
  color: #5a6b7c;
  text-align: left;
  white-space: nowrap;
  border-bottom: 1px solid #e0e4e8;
}

/* Data rows */
.mat-row {
  font-size: 11px;
  color: #23313f;
  border-bottom: 1px solid #e0e4e8;
}

.mat-row:nth-child(even) {
  background: #fafbfc;
}

.mat-row:hover {
  background: #e9f2fb;
}

/* Cells */
.mat-cell {
  padding: 6px 8px;
  white-space: nowrap;
  text-align: left;
}

/* First visible column (Created time) a bit more left-padded */
.mat-header-row .mat-header-cell:first-child,
.mat-row .mat-cell:first-child {
  padding-left: 12px;
}

/* Severity column: bold, uppercase, centered ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“pill-ishÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â look */

.mat-header-row .mat-header-cell:nth-child(4),
.mat-row .mat-cell:nth-child(4) {
  text-align: center;
}


.mat-row .mat-cell:nth-child(4) {
  font-weight: 700;
  text-transform: uppercase;
  font-size: 11px;
}

/* Make the severity text sit on a soft pill background */
.mat-row .mat-cell:nth-child(4) span,
.mat-row .mat-cell:nth-child(4) {
  display: inline-block;
  min-width: 56px;
  padding: 3px 8px;
  border-radius: 12px;
  background: rgba(211, 47, 47, 0.1);   /* light red behind TBÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢s red text */
}

/* Action / icon columns right-aligned and tighter */
.mat-header-row .mat-header-cell:last-child,
.mat-row .mat-cell:last-child {
  text-align: right;
}

/* OPTIONAL: hide paginator bar if you do not need it */
.mat-paginator {
  display: none !important;
}

/* Tighten the right-hand columns: Assignee + action icons */
.mat-header-row .mat-header-cell:nth-last-child(-n+4),
.mat-row .mat-cell:nth-last-child(-n+4) {
  padding-left: 4px;
  padding-right: 4px;
  text-align: center;
}

/* Keep other columns with normal padding */
.mat-header-row .mat-header-cell,
.mat-row .mat-cell {
  padding-top: 6px;
  padding-bottom: 6px;
}
